import { expect, userEvent, within } from 'storybook/test';
import React, { useState } from 'react';
import { ZimmSizeChipGroup } from './index';
import type { ZimmSizeChipValue } from './index';

const meta: Meta<typeof ZimmSizeChipGroup> = {
  title: 'Commerce/ZimmSizeChipGroup',
  component: ZimmSizeChipGroup,
  parameters: { layout: 'padded' },
};

export default meta;
type Story = StoryObj<typeof ZimmSizeChipGroup>;

const SIZES: ZimmSizeChipValue[] = [
  { value: 'xs', label: 'XS' },
  { value: 's', label: 'S' },
  { value: 'm', label: 'M' },
  { value: 'l', label: 'L' },
  { value: 'xl', label: 'XL' },
];

const DefaultExample = () => {
  const [selectedValue, setSelectedValue] = useState<string | undefined>('');
  return <ZimmSizeChipGroup values={SIZES} selectedValue={selectedValue} onSelect={setSelectedValue} />;
};

/** Multi-size row, nothing selected initially — click a chip to see the live selection. */
export const Default: Story = {
  render: () => <DefaultExample />,
};

const WithSelectionExample = () => {
  const [selectedValue, setSelectedValue] = useState<string | undefined>('m');
  return <ZimmSizeChipGroup values={SIZES} selectedValue={selectedValue} onSelect={setSelectedValue} />;
};

/** A size pre-selected — its chip renders with the selected treatment and is the tab stop. Click
 *  a different chip to move the live selection, same as `Default` above. */
export const WithSelection: Story = {
  render: () => <WithSelectionExample />,
};

const SIZES_WITH_DISABLED: ZimmSizeChipValue[] = [
  { value: 'xs', label: 'XS' },
  { value: 's', label: 'S', isDisabled: true },
  { value: 'm', label: 'M' },
  { value: 'l', label: 'L' },
];

const WithDisabledSizeExample = () => {
  const [selectedValue, setSelectedValue] = useState<string | undefined>('m');
  return <ZimmSizeChipGroup values={SIZES_WITH_DISABLED} selectedValue={selectedValue} onSelect={setSelectedValue} />;
};

/** One size unavailable — shown disabled (not withheld), so the full size run stays visible.
 *  Click any enabled chip to move the live selection; the disabled chip stays unselectable via
 *  its own native `disabled` attribute. */
export const WithDisabledSize: Story = {
  render: () => <WithDisabledSizeExample />,
};

/** The size-chip Figma component set's other Type — a single non-interactive label, not a
 *  one-item radiogroup. */
export const OneSize: Story = {
  args: {
    values: [{ value: 'os', label: 'One size' }],
  },
};

const KeyboardNavigationExample = () => {
  const [selectedValue, setSelectedValue] = useState<string | undefined>('xs');
  return <ZimmSizeChipGroup values={SIZES} selectedValue={selectedValue} onSelect={setSelectedValue} />;
};

/** Arrow-key navigation — ArrowRight moves both the roving tab stop and the selection. */
export const KeyboardNavigation: Story = {
  render: () => <KeyboardNavigationExample />,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const first = canvas.getByRole('radio', { name: 'XS' });
    await userEvent.click(first);
    await userEvent.keyboard('{ArrowRight}');
    const second = canvas.getByRole('radio', { name: 'S' });
    await expect(second).toHaveFocus();
    await expect(second).toHaveAttribute('aria-checked', 'true');
  },
};

/**
 * Scoped per testing.md: this organism's own contract (given a variation + props, does it render
 * the right children with the right flags, and does every interactive control still fire its own
 * callback) — not ZimmProductCardMedia/ZimmProductCardContent's own internal logic, which is
 * already proven in their own index.test.tsx files. Both are composed for real here (not mocked
 * out), the same "costs nothing, gives real integration confidence" precedent
 * zimmProductCardContent/index.test.tsx already documents for its own composed atoms/molecules.
 *
 * Only `useMultiStyleConfig` is mocked, with one flat object covering every part every composed
 * descendant reads (`ZimmProductCardMedia`, `ZimmSlideIndicator`, `ZimmProductCardContent`,
 * `ZimmProductPrice`, `ZimmSizeChipGroup`, `ZimmSizeChip`, and this organism's own `root`) — same
 * "neither test setup nor Chakra cares which recipe name asked for it" precedent
 * zimmProductCardMedia/index.test.tsx documents. `ZimmProductName`'s `useStyleConfig` call is left
 * real/unmocked, same as zimmProductCardContent/index.test.tsx.
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { chakra } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { ZimmProductCard } from './index';
import type {
  ZimmProductCardProps,
  ZimmProductCardImage,
  ZimmProductCardBaseProps,
  ZimmProductCardPlpVariation,
  ZimmProductCardHomeVariation,
  ZimmProductCardWishlistVariation,
} from './index';
import { ZimmProductCard as ZimmProductCardRecipe } from './zimmProductCard.css';
// Fix 1 (Scorer rework round 1): needed to compose the REAL close-part style object this
// organism's root recipe cascades against — see the "Fix 1" describe block below. `chakra` above
// is imported the normal way (not via vi.importActual) because the vi.mock('@chakra-ui/react', ...)
// factory below spreads `...actual` and only overrides `useMultiStyleConfig` — `chakra` itself
// was never mocked, so this import already resolves to the real Emotion-backed factory.
import { ZimmProductCardMedia as ZimmProductCardMediaRecipe } from '../../molecules/zimmProductCardMedia/zimmProductCardMedia.css';
// Fix D: the real `breakpoints.md` value, so DESKTOP_QUERY below can't drift from the source
// file's own derivation of it. No DOM-level compose-and-read proof for this one (unlike Fix 1/3/
// C above) — those all resolve a STATIC declaration; jsdom's actual support for resolving a real
// `min-width` media query against getComputedStyle is unreliable enough that the object-shape
// assertions below, plus the real-browser check every hover/pointer concern in this file's own
// "KNOWN LIMITATION" docblock already defers to, are the honest level of proof here.
import { breakpoints } from 'app/theme/foundation';
import { CARD_SLOT, HOVER_CAPABLE_QUERY } from '../../zimmProductCardShared';

/**
 * Fix G's own contribution is a boolean `index.tsx` COMPUTES (`bagHiddenOnMobile`, combining two
 * VARIATION_CONFIG fields with `isUnavailable`) before ever calling `useMultiStyleConfig` — the
 * "real recipe assertions" pattern used everywhere else in this file proves the RECIPE reacts
 * correctly to a given `hideBagOnMobile` value, but says nothing about whether index.tsx computed
 * the right value in the first place. `vi.hoisted` lets this mock factory (hoisted above the rest
 * of the file by Vitest) share a capture slot with the test body below, without hitting a TDZ
 * error from referencing an un-hoisted `let`.
 */
const { capturedOrganismStyleProps } = vi.hoisted(() => ({
  capturedOrganismStyleProps: { current: undefined as Record<string, unknown> | undefined },
}));

